// SO Save V2: there is no scheduled worker - a save no form is following any more (a closed tab, a closed browser) moves on
// when the SO list opens (at most every 30 seconds per browser), as the GD list does for its jobs: the tenant's due saves
// (SO_SAVE_RUN without a job), and the delivery edits those saves released (GD_EDIT_WORKER). Each one again while it moves.
(() => {
  const KEY = "sov2_worker_kick_at";
  let last = 0;
  try {
    last = Number(localStorage.getItem(KEY) || 0);
  } catch (e) {}
  if (Date.now() - last < 30000) return;
  try {
    localStorage.setItem(KEY, String(Date.now()));
  } catch (e) {}
  // answered: called once, when this run first answers (success or failure) - starts the next worker
  const tick = (workflowId, round, moved, answered) => {
    const done = () => {
      if (answered) answered();
      answered = null;
    };
    try {
      this.runWorkflow(
        workflowId,
        {},
        (w) => {
          done();
          if (moved((w && w.data) || {})) {
            this.refresh();
            if (round < 40) tick(workflowId, round + 1, moved);
          }
        },
        (e) => {
          console.error("SO Save V2: worker tick failed", workflowId, e);
          done();
        },
      );
    } catch (e) {
      console.error("SO Save V2: worker could not be started", workflowId, e);
      done();
    }
  };
  const processed = (d) => Number(d.processed || 0) > 0;
  // One after the other, never in the same instant: the backend can lose a code node's script when two workflows load
  // their scripts at the same moment after a restart ("script for node[...] is not loaded", GUB staging 2026-10-22).
  tick("2113116286771331073", 1, processed, () => {
    // SO_SAVE_RUN (drain: the tenant's due saves) answered
    tick("2110618789356687361", 1, processed); // GD_EDIT_WORKER (the delivery edits a save released)
  });
})();

