// ---- SO Save V2: an order being saved in the background (sales_order.is_processing = 1) opens for nothing -------------
// docs/lowcode/so-save-v2/PLAN.md. Inserted by scripts/build-so-list-v2.mjs at the top of the SO list's open handlers
// (View, Edit, Clone, Convert WO, the SO number, the line tab's View / Edit), as the GD list does for a Processing GD.
// The list row can be stale, so the order is read again before it opens. A save waiting for an answer opens (the form
// asks it: so_mounted_guard.js).
const sov2BeingSaved = async (soId) => {
  if (!soId) return false;
  try {
    const res = await db.collection("sales_order").where({ id: soId, is_deleted: 0 }).get();
    const so = (res && res.data && res.data[0]) || null;
    if (so && Number(so.is_processing) === 1) {
      // a save waiting for an answer (its tab closed at the question): the order opens and asks it
      const jobs = await db.collection("gd_async_job").where({ correlation_id: "SO|" + soId, job_status: "AWAITING_CONFIRMATION", is_deleted: 0 }).get();
      if (jobs && jobs.data && jobs.data.length) {
        this.$message.info("This sales order is waiting for your answer to finish saving.");
        return false;
      }
      console.log("SO Save V2: being saved, not opened", soId);
      this.$message.warning("This sales order is being saved in the background. Please wait until it finishes, then open it again.");
      return true;
    }
  } catch (e) {
    console.error("SO Save V2: could not check the sales order", e);
  }
  return false;
};

(async () => {
  if (await sov2BeingSaved(arguments[0].row.id)) return;
  this.routeLocation(
      {
      routeMode: "dialog",
          routeInfo: {
              source_id: "1905448861495791617",
              name:"Sales Order Form",	
          },
      },
      {   
          "sales_order_id": arguments[0].row.id,
          "page_status": "View"		
      }
  );
})();

