const checkExistingGoodsDelivery = async (soID) => {
  const resGD = await db
    .collection("goods_delivery")
    .filter([
      {
        type: "branch",
        operator: "all",
        children: [
          {
            prop: "so_id",
            operator: "in",
            value: soID,
          },
          {
            prop: "gd_status",
            operator: "equal",
            value: "Draft",
          },
        ],
      },
    ])
    .get();

  if (!resGD || resGD.data.length === 0) return [];
  return resGD.data;
};

