      this.showLoading();
      await deleteRelatedGD(existingGD);
      await deleteRelatedSI(existingSI);
    }

    if (existingCreatedGD.length > 0) {
      this.hideLoading();
      await this.$alert(
        `${
          existingCreatedGD.length > 0
            ? "The sales order has existing goods delivery records in created status. Please cancel all associated goods delivery records before proceeding."
