/*
 * 自定义打印模板按钮事件：关联模板直接打印；未关联时，单模板自动打印、多模板弹框选择。
 * Custom print event: use a linked template directly; otherwise auto-print one match or show a picker for multiple matches.
 * 保留原接口参数和 openpage 地址；注释中英双语，文案跟随 this.$i18n.locale（字符串/ref）。
 * Keep API parameters and the openpage URL unchanged; bilingual comments and messages follow this.$i18n.locale (string/ref).
 * 内置中英文文案，无语言信息时默认中文；可用 custom.printTemplatePrint.* 语言包键覆盖。
 * Built-in Chinese/English messages default to Chinese without locale information; custom.printTemplatePrint.* keys can override them.
 * 模板名称、业务字段及接口原始错误保持原样。 / Preserve template names, business fields and original API errors.
 */
(async () => {
  const [{ item = {} } = {}] = arguments;
  const PAGE_API = "2021782616872640514";
  const MATCH_API = "2021841685763379201";
  const responseKeys = ["data", "result", "records", "list", "items"];
  let loadingVisible = false;

  // 文案集中管理，依次为中文、英文。 / Centralized messages: Chinese, then English.
  const messages = {
    prefix: ["打印模板", "Print template"],
    unnamed: ["未命名打印模板", "Unnamed print template"],
    choose: ["选择模板", "Select template"],
    close: ["关闭", "Close"],
    cancel: ["取消", "Cancel"],
    print: ["打印", "Print"],
    configureTable: ["请先配置业务表", "Please configure the business table first"],
    selectRows: ["请先勾选需要打印的数据", "Please select the records to print first"],
    missingTable: ["没有获取到页面业务表格组件实例", "The business table component instance is unavailable"],
    missingIds: ["部分勾选数据没有主键ID", "Some selected records have no primary key ID"],
    loadingTemplates: ["正在获取符合条件的打印模板...", "Loading matching print templates..."],
    noTemplates: ["当前数据没有匹配到可用的打印模板", "No available print templates matched the selected records"],
    loadingPrint: ["正在准备打印，共{count}条数据...", "Preparing to print {count} records..."],
    missingPage: ["没有获取到打印模板对应的页面ID", "The page ID for the print template is unavailable"],
    missingBusinessTable: ["没有查询到工具栏配置的业务表", "The business table configured in the toolbar was not found"],
    missingTableName: ["业务表英文名称不能为空", "The business table name cannot be empty"],
    previewFailed: ["打开打印预览失败", "Failed to open the print preview"],
    logTables: ["页面表格组件：", "Page table components:"],
    logConfig: ["工具栏配置：", "Toolbar configuration:"],
    logInvalidRows: ["部分勾选数据没有主键ID：", "Selected records without primary key IDs:"],
    logRows: ["当前勾选数据：", "Selected records:"],
    logTemplates: ["条件匹配模板接口返回：", "Matching template API response:"],
    logSingle: ["仅匹配到一个模板，直接打印：", "One template matched; print directly:"],
    logChosen: ["本次选择的打印模板：", "Selected print template:"],
    logPage: ["打印页面接口返回：", "Print page API response:"],
    logPrint: ["打开批量打印：", "Open batch print:"],
    logFailed: ["批量打印执行失败：", "Batch printing failed:"]
  };
  const t = (key, params = {}) => {
    const path = "custom.printTemplatePrint." + key;
    try {
      if (typeof this.$t === "function" && typeof this.$te === "function" && this.$te(path)) {
        const translated = this.$t(path, params);
        if (typeof translated === "string" && translated && translated !== path) return translated;
      }
    } catch {} // 翻译不可用时使用内置文案。 / Use built-in messages if host translation is unavailable.
    const current = this.$i18n?.locale;
    const locale = String((typeof current === "string" ? current : current?.value) || "zh-cn");
    return messages[key][locale.trim().toLowerCase().startsWith("zh") ? 0 : 1]
      .replace(/\{(\w+)\}/g, (match, name) => params[name] == null ? match : String(params[name]));
  };
  const log = (level, key, ...args) => console[level]("[" + t("prefix") + "] " + t(key), ...args);
  const showLoading = (key, params) => { this.showLoading(t(key, params)); loadingVisible = true; };
  const hideLoading = () => { if (loadingVisible) { this.hideLoading(); loadingVisible = false; } };
  const warn = (key) => this.showToast(t(key), "warning");
  const configId = (value) => {
    if (Array.isArray(value)) return configId(value[0]);
    return String((value && typeof value === "object"
      ? value.value || value.id || value.tableId || value.templateId : value) || "");
  };
  const rowId = (row) => row?.id || row?._id || row?.ID;
  const normalizeRows = (value) => Array.isArray(value) ? value : Array.isArray(value?.value) ? value.value : null;

  // 保留勾选实例查找顺序，兼容数组/ref。 / Preserve selection lookup order and support arrays/refs.
  const selectedTables = () => {
    const tables = [];
    for (const [componentKey, value] of Object.entries(this.getComponent?.() || {})) {
      for (const component of Array.isArray(value) ? value : [value]) {
        const rows = [
          component?.$refs?.crud?.tableSelect,
          component?.$refs?.crud?.$refs?.crud?.tableSelect,
          component?.$refs?.crud?.crud?.tableSelect,
          component?.$refs?.table?.tableSelect,
          component?.tableSelect
        ].map(normalizeRows).find((rows) => rows !== null);
        if (rows) tables.push({ componentKey, rows });
      }
    }
    log("log", "logTables", tables.map(({ componentKey, rows }) => ({ componentKey, checkedCount: rows.length })));
    return tables;
  };

  // 共用递归解析；页面只扫描固定响应键，模板列表也扫描其他包装键。
  // Shared response traversal: fixed keys for pages; additional wrapper keys for template lists.
  const findResponse = (value, pick, limit = 8, scanAll = false, depth = 0) => {
    if (!value || depth > limit) return null;
    const found = pick(value);
    if (found) return found;
    if (typeof value !== "object") return null;
    const children = Array.isArray(value) ? value
      : (scanAll ? [...responseKeys, ...Object.keys(value).filter((key) => !responseKeys.includes(key))] : responseKeys)
        .map((key) => value[key]);
    for (const child of children) {
      const result = findResponse(child, pick, limit, scanAll, depth + 1);
      if (result) return result;
    }
    return null;
  };
  const normalizeTemplates = (response) => {
    const rows = findResponse(response, (value) => {
      if (!Array.isArray(value)) return null;
      const rows = value.filter((row) => row && typeof row === "object" && (row.id || row.templateId)
        && (row.temp_name || row.template_name || row.name || row.title));
      return rows.length ? rows : null;
    }, 8, true) || [];
    const seen = new Set();
    return rows.reduce((templates, row) => {
      const id = configId(row.id || row.templateId), enabled = row.enabled;
      const isEnabled = enabled == null || enabled === "" || enabled === true || enabled === 1
        || ["1", "true", "enabled"].includes(String(enabled ?? "").toLowerCase());
      if (id && isEnabled && !seen.has(id)) {
        seen.add(id);
        templates.push({ id, name: String(row.temp_name || row.template_name || row.name || row.title || t("unnamed")) });
      }
      return templates;
    }, []);
  };

  // 原生 DOM 弹框：两列布局，取消/关闭/Escape 返回空ID，不使用 innerHTML。
  // Native DOM picker: two columns; Cancel/Close/Escape return an empty ID; no innerHTML.
  const selectTemplate = (templates) => new Promise((resolve) => {
    if (!Array.isArray(templates) || !templates.length) { resolve(""); return; }
    const make = (tag, style, text) => {
      const node = document.createElement(tag);
      Object.assign(node.style, style);
      if (text != null) node.textContent = text;
      return node;
    };
    const button = (text, primary = false) => {
      const node = make("button", {
        height: "30px", padding: "0 15px", border: "1px solid " + (primary ? "#409eff" : "#dcdfe6"),
        borderRadius: "3px", background: primary ? "#409eff" : "#ffffff",
        color: primary ? "#ffffff" : "#606266", cursor: "pointer", fontSize: "13px"
      }, text);
      node.type = "button";
      return node;
    };
    const overlay = make("div", {
      position: "fixed", inset: "0", zIndex: "20000", display: "flex", alignItems: "center",
      justifyContent: "center", padding: "16px", background: "rgba(0, 0, 0, 0.5)"
    });
    const dialog = make("div", {
      width: "600px", maxWidth: "calc(100vw - 32px)", maxHeight: "calc(100vh - 48px)",
      overflow: "hidden", borderRadius: "4px", background: "#ffffff", boxShadow: "0 12px 32px rgba(0, 0, 0, 0.2)"
    });
    const header = make("div", {
      display: "flex", alignItems: "center", justifyContent: "space-between", height: "44px",
      padding: "0 14px", borderBottom: "1px solid #ebeef5", color: "#303133", fontSize: "14px", fontWeight: "600"
    });
    const close = make("button", {
      padding: "0", border: "0", background: "transparent", color: "#909399",
      cursor: "pointer", fontSize: "20px", lineHeight: "1"
    }, "×");
    close.type = "button";
    close.setAttribute("aria-label", t("close"));
    header.append(make("span", {}, t("choose")), close);
    const body = make("div", {
      display: "grid", gridTemplateColumns: "repeat(2, minmax(0, 1fr))", gridAutoRows: "28px",
      alignContent: "start", columnGap: "32px", rowGap: "12px", minHeight: "88px", maxHeight: "280px",
      overflowY: "auto", boxSizing: "border-box", padding: "20px 24px"
    });
    const radioName = "print-template-" + Date.now() + "-" + Math.random();
    let selectedId = templates[0].id, finished = false;
    templates.forEach((template, index) => {
      const label = make("label", {
        display: "flex", alignItems: "center", height: "28px", minWidth: "0",
        color: "#606266", cursor: "pointer", fontSize: "14px"
      });
      const radio = make("input", { width: "15px", height: "15px", margin: "0 8px 0 0", accentColor: "#409eff", cursor: "pointer" });
      Object.assign(radio, { type: "radio", name: radioName, value: template.id, checked: index === 0 });
      radio.addEventListener("change", () => { selectedId = template.id; });
      label.append(radio, make("span", { overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }, template.name));
      body.append(label);
    });
    const footer = make("div", {
      display: "flex", justifyContent: "flex-end", gap: "10px", padding: "10px 14px", borderTop: "1px solid #ebeef5"
    });
    const cancel = button(t("cancel")), print = button(t("print"), true);
    footer.append(cancel, print);
    dialog.append(header, body, footer);
    overlay.append(dialog);
    document.body.append(overlay);
    const finish = (id) => {
      if (finished) return;
      finished = true;
      document.removeEventListener("keydown", onKeydown);
      overlay.remove();
      resolve(id);
    };
    const onKeydown = (event) => { if (event.key === "Escape") finish(""); };
    close.addEventListener("click", () => finish(""));
    cancel.addEventListener("click", () => finish(""));
    print.addEventListener("click", () => finish(selectedId));
    document.addEventListener("keydown", onKeydown);
  });

  try {
    const businessTableId = configId(item.businessTable || item.businessTableId || item.tableId || item.business_table_id);
    let printTemplateId = configId(item.templateId || item.printTemplate || item.printTemplateId);
    log("log", "logConfig", { businessTableId, printTemplateId, item });
    if (!businessTableId) { warn("configureTable"); return; }

    // 必须先勾选数据，再请求模板或弹框。 / Validate selected records before fetching templates or showing a dialog.
    const tables = selectedTables(), selected = tables.find((table) => table.rows.length > 0);
    if (!selected) { warn(tables.length ? "selectRows" : "missingTable"); return; }
    const invalidRows = selected.rows.filter((row) => !rowId(row));
    if (invalidRows.length) {
      log("error", "logInvalidRows", invalidRows);
      warn("missingIds");
      return;
    }
    const ids = [...new Set(selected.rows.map((row) => String(rowId(row))))];
    log("log", "logRows", { componentKey: selected.componentKey, count: ids.length, ids, checkedRows: selected.rows });

    // 关联模板不请求匹配接口；未关联时只按勾选记录匹配一次，不回退查询业务表全部模板。
    // Linked templates bypass matching; otherwise match selected records once without a table-only fallback.
    if (!printTemplateId) {
      showLoading("loadingTemplates");
      const response = await this.callApi(MATCH_API, {}, { tableId: businessTableId, dataId: ids });
      log("log", "logTemplates", response);
      const templates = normalizeTemplates(response);
      hideLoading();
      if (!templates.length) { warn("noTemplates"); return; }
      printTemplateId = templates.length === 1 ? templates[0].id : await selectTemplate(templates);
      if (!printTemplateId) return;
      log("log", templates.length === 1 ? "logSingle" : "logChosen", printTemplateId);
    }

    showLoading("loadingPrint", { count: ids.length });
    const pageResponse = await this.callApi(PAGE_API, {}, { id: printTemplateId });
    log("log", "logPage", pageResponse);
    const pageInfo = findResponse(pageResponse,
      (value) => typeof value === "object" && !Array.isArray(value) && (value.pageId || value.page_id) ? value : null, 6);
    const pageId = String(pageInfo?.pageId || pageInfo?.page_id || "");
    if (!pageId) throw new Error(t("missingPage"));

    const tableResponse = await db.collection("su_code_tables").doc(businessTableId).field("id,name,table_name").get();
    const tableInfo = Array.isArray(tableResponse?.data) ? tableResponse.data[0] : tableResponse?.data || null;
    if (!tableInfo) throw new Error(t("missingBusinessTable"));
    const tableName = String(tableInfo.table_name || "").trim().replace(/[^a-zA-Z0-9_]/g, "_").replace(/^_+|_+$/g, "");
    if (!tableName) throw new Error(t("missingTableName"));

    // 一个页面传递逗号分隔的全部主键；URL及name生成规则不变。
    // Open one page with all comma-separated IDs; preserve URL and name generation rules.
    const parameterName = tableName + "_id";
    const pageName = tableName.split("_").filter(Boolean).map((word) => word.charAt(0).toUpperCase() + word.slice(1)).join("+");
    const openPageUrl = "/sucode/openpage/" + pageId + "?" + parameterName + "=" + ids.join(",") + "&name=" + pageName;
    log("log", "logPrint", { businessTableId, printTemplateId, templateID: pageId, parameterName, ids, pageName, openPageUrl });
    hideLoading();
    return window.open(openPageUrl);
  } catch (error) {
    log("error", "logFailed", error);
    this.showToast(error?.message || t("previewFailed"), "error");
  } finally {
    hideLoading();
  }
})();

